def is_ip_blocked(ip_str: str) -> bool:
    """Check if an IP address is in a blocked range (SSRF protection)."""
    try:
        ip = ipaddress.ip_address(ip_str)
        for blocked_range in BLOCKED_IP_RANGES:
            if ip in blocked_range:
                return True
        return False
    except ValueError:
        return True  # Block invalid IPs


def validate_url_safety(url: str) -> None:
    """
    Validate URL for security issues including SSRF protection.
    Raises HTTPException if URL is not safe.
    """
    parsed = urlparse(url)

    # Check scheme
    if parsed.scheme not in ALLOWED_SCHEMES:
        raise HTTPException(
            status_code=400,
            detail=f"URL scheme '{parsed.scheme}' is not allowed. Use http or https.",
        )

    # Check hostname exists
    hostname = parsed.hostname
    if not hostname:
        raise HTTPException(status_code=400, detail="Invalid URL: missing hostname")

    # Block localhost variants
    localhost_names = {"localhost", "local", "broadcasthost"}
    if hostname.lower() in localhost_names:
        raise HTTPException(
            status_code=403,
            detail="Access to localhost is not allowed",
        )

    # Resolve hostname and check IP
    try:
        addr_infos = socket.getaddrinfo(hostname, None)
        for addr_info in addr_infos:
            ip_str = addr_info[4][0]
            if is_ip_blocked(ip_str):
                raise HTTPException(
                    status_code=403,
                    detail=f"Access to private/internal IP addresses is not allowed",
                )
    except socket.gaierror:
        raise HTTPException(
            status_code=400,
            detail=f"Could not resolve hostname: {hostname}",
        )


def sanitize_response_headers(headers: dict) -> dict:
    """Remove sensitive headers from the response."""
    sensitive_headers = {
        "set-cookie",
        "www-authenticate",
        "proxy-authenticate",
    }
    return {
        key: value
        for key, value in headers.items()
        if key.lower() not in sensitive_headers
    }


