@app.get("/fetch", response_model=FetchResponse)
async def fetch_url_get(
    url: str = Query(..., description="The URL to fetch"),
    timeout: int = Query(default=30, ge=1, le=60, description="Request timeout in seconds"),
):
    """
    Fetch data from an external URL via GET request.

    - **url**: The external URL to fetch
    - **timeout**: Request timeout in seconds (1-60)
    """
    # Validate URL safety
    validate_url_safety(url)

    try:
        async with httpx.AsyncClient(
            follow_redirects=True,
            max_redirects=MAX_REDIRECTS,
            timeout=httpx.Timeout(timeout),
            limits=httpx.Limits(max_connections=10),
        ) as client:
            response = await client.get(
                url,
                headers={
                    "User-Agent": "URLFetcherAPI/1.0",
                },
            )

            # Check response size
            content = response.content
            if len(content) > MAX_RESPONSE_SIZE:
                raise HTTPException(
                    status_code=413,
                    detail=f"Response too large. Maximum allowed size is {MAX_RESPONSE_SIZE // (1024*1024)} MB",
                )

            # Decode body safely
            content_type = response.headers.get("content-type", "")
            try:
                body = content.decode("utf-8", errors="replace")
            except Exception:
                body = content.decode("latin-1", errors="replace")

            return FetchResponse(
                url=str(response.url),
                status_code=response.status_code,
                headers=sanitize_response_headers(dict(response.headers)),
                content_type=content_type,
                body=body,
                elapsed_ms=response.elapsed.total_seconds() * 1000,
                size_bytes=len(content),
            )

    except httpx.TimeoutException:
        raise HTTPException(
            status_code=504,
            detail=f"Request timed out after {timeout} seconds",
        )
    except httpx.TooManyRedirects:
        raise HTTPException(
            status_code=502,
            detail=f"Too many redirects (max: {MAX_REDIRECTS})",
        )
    except httpx.RequestError as e:
        logger.error(f"Request error fetching {url}: {e}")
        raise HTTPException(
            status_code=502,
            detail=f"Failed to fetch URL: {str(e)}",
        )


