    except httpx.TimeoutException:
        raise HTTPException(
            status_code=504,
            detail=f"Request timed out after {request.timeout} seconds",
        )
    except httpx.TooManyRedirects:
        raise HTTPException(
            status_code=502,
            detail=f"Too many redirects (max: {MAX_REDIRECTS})",
